namespace CheckoutPricing.Application.Checkout;

public enum CustomerTier
{
    Standard,
    Gold,
}

public sealed record CalculatePayableTotalCommand(CustomerTier Tier, decimal OrderSubtotal);

public sealed class CalculatePayableTotalHandler
{
    public decimal Handle(CalculatePayableTotalCommand command) => command.OrderSubtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/Checkout/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application.Checkout;

namespace CheckoutPricing.UnitTests.Checkout;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void Gold_customer_with_100_subtotal_pays_95()
    {
        var handler = new CalculatePayableTotalHandler();

        var payable = handler.Handle(new CalculatePayableTotalCommand(CustomerTier.Gold, 100.00m));

        Assert.Equal(95.00m, payable);
    }
}
